<?php
require __DIR__.'/_init.php';require_login();$userId=(int)$_SESSION['user']['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('UPDATE notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE user_id=?')->execute([$userId]);flash('Notifications marked as read.');header('Location: /notifications.php');exit;}
$query=db()->prepare('SELECT n.id,n.request_id,n.message,n.read_at,n.created_at,r.tracking_id,r.title FROM notifications n JOIN service_requests r ON r.id=n.request_id WHERE n.user_id=? ORDER BY n.created_at DESC LIMIT 50');$query->execute([$userId]);$items=$query->fetchAll();page_start('Notifications');?>
<div class="row"><div><div class="eyebrow">REQUEST UPDATES</div><h1>Notifications</h1></div><?php if($items):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><button class="button small">Mark all read</button></form><?php endif;?></div><?php if(!$items):?><div class="empty"><h3>All quiet for now</h3><p>Status changes on your requests will show here.</p></div><?php else:?><div class="notification-list"><?php foreach($items as $item):?><article class="notification <?=$item['read_at']?'':'unread'?>"><p><?=e($item['message'])?></p><a href="/request.php?id=<?=e($item['request_id'])?>"><?=e($item['tracking_id'])?> · <?=e($item['title'])?></a><small><?=e($item['created_at'])?></small></article><?php endforeach;?></div><?php endif;?><?php page_end();?>
